  "n": 3,
  "zh": "週末做什麼？",
  "en": "What Are You Doing Over the Weekend?",
  "topic": "Hobbies",
  "speak": [
   {
    "title": "會話練習 Speaking practice",
    "items": [
     {
      "q": {
       "zh": "你喜歡聽音樂嗎？",
       "en": "Do you like listening to music?",
       "id": "Kamu suka mendengarkan musik?",
       "ja": "音楽を聴くのは好きですか？",
       "py": "Nǐ xǐhuān tīng yīnyuè ma?",
       "a": "af653fe106bd"
      },
      "ans": {
       "zh": "我很喜歡聽音樂，也喜歡運動。",
       "en": "I really like listening to music, and I also like sports.",
       "id": "Saya sangat suka mendengarkan musik, juga suka olahraga.",
       "ja": "音楽を聴くのが大好きで、運動も好きです。",
       "py": "Wǒ hěn xǐhuān tīng yīnyuè, yě xǐhuān yùndòng.",
       "a": "619fb06f2758"
      }
     },
     {
      "q": {
       "zh": "你喜歡做什麼運動？",
       "en": "What sports do you like to do?",
       "id": "Kamu suka olahraga apa?",
       "ja": "どんな運動が好きですか？",
       "py": "Nǐ xǐhuān zuò shénme yùndòng?",
       "a": "e5915d2f9ca7"
      },
      "ans": {
       "zh": "我喜歡打籃球和游泳。",
       "en": "I like playing basketball and swimming.",
       "id": "Saya suka main basket dan berenang.",
       "ja": "バスケットボールと水泳が好きです。",
       "py": "Wǒ xǐhuān dǎ lánqiú hàn yóuyǒng.",
       "a": "474af2487d41"
      }
     },
     {
      "q": {
       "zh": "你常打網球嗎？",
       "en": "Do you often play tennis?",
       "id": "Kamu sering main tenis?",
       "ja": "よくテニスをしますか？",
       "py": "Nǐ cháng dǎ wǎngqiú ma?",
       "a": "77210a2ed599"
      },
      "ans": {
       "zh": "我不常打網球，我常踢足球。",
       "en": "I don't often play tennis. I often play soccer.",
       "id": "Saya tidak sering main tenis, saya sering main sepak bola.",
       "ja": "テニスはあまりしません。よくサッカーをします。",
       "py": "Wǒ bù cháng dǎ wǎngqiú, wǒ cháng tī zúqiú.",
       "a": "b06f42fb780b"
      }
     },
     {
      "q": {
       "zh": "你覺得打棒球好玩嗎？",
       "en": "Do you think playing baseball is fun?",
       "id": "Menurutmu main bisbol seru?",
       "ja": "野球は楽しいと思いますか？",
       "py": "Nǐ juéde dǎ bàngqiú hǎowán ma?",
       "a": "642d9e02a795"
      },
      "ans": {
       "zh": "我覺得打棒球很好玩。",
       "en": "I think playing baseball is a lot of fun.",
       "id": "Menurut saya main bisbol seru sekali.",
       "ja": "野球はとても楽しいと思います。",
       "py": "Wǒ juéde dǎ bàngqiú hěn hǎowán.",
       "a": "2137a87eee1a"
      }
     },
     {
      "q": {
       "zh": "週末你想做什麼？",
       "en": "What do you want to do on the weekend?",
       "id": "Akhir pekan kamu mau melakukan apa?",
       "ja": "週末は何をしたいですか？",
       "py": "Zhōumò nǐ xiǎng zuò shénme?",
       "a": "fb5717579e88"
      },
      "ans": {
       "zh": "週末我想去看電影。",
       "en": "On the weekend I want to go see a movie.",
       "id": "Akhir pekan saya mau nonton film.",
       "ja": "週末は映画を見に行きたいです。",
       "py": "Zhōumò wǒ xiǎng qù kàn diànyǐng.",
       "a": "cb71a78aede3"
      }
     },
     {
      "q": {
       "zh": "你想看美國電影還是臺灣電影？",
       "en": "Do you want to see an American movie or a Taiwanese movie?",
       "id": "Kamu mau nonton film Amerika atau film Taiwan?",
       "ja": "アメリカ映画と台湾映画、どちらが見たいですか？",
       "py": "Nǐ xiǎng kàn Měiguó diànyǐng háishì Táiwān diànyǐng?",
       "a": "f283a42ad393"
      },
      "ans": {
       "zh": "我想看臺灣電影，看電影可以學中文。",
       "en": "I want to see a Taiwanese movie. Watching movies helps you learn Chinese.",
       "id": "Saya mau nonton film Taiwan, nonton film bisa belajar bahasa Mandarin.",
       "ja": "台湾映画が見たいです。映画を見ると中国語の勉強になります。",
       "py": "Wǒ xiǎng kàn Táiwān diànyǐng, kàn diànyǐng kěyǐ xué Zhōngwén.",
       "a": "00dd789d83e0"
      }
     },
     {
      "q": {
       "zh": "今天晚上我們一起吃晚飯，好不好？",
       "en": "Shall we have dinner together tonight?",
       "id": "Malam ini kita makan malam bersama, yuk?",
       "ja": "今晩一緒に晩ご飯を食べませんか？",
       "py": "Jīntiān wǎnshàng wǒmen yìqǐ chī wǎnfàn, hǎo bù hǎo?",
       "a": "b91bb792280c"
      },
      "ans": {
       "zh": "好啊！我們去吃越南菜，怎麼樣？",
       "en": "Sure! How about we go eat Vietnamese food?",
       "id": "Boleh! Bagaimana kalau kita makan masakan Vietnam?",
       "ja": "いいですね！ベトナム料理を食べに行くのはどうですか？",
       "py": "Hǎo a! Wǒmen qù chī Yuènán cài, zěnmeyàng?",
       "a": "56e3be2d664f"
      }
     },
     {
      "q": {
       "zh": "明天早上我們去踢足球，怎麼樣？",
       "en": "How about we go play soccer tomorrow morning?",
       "id": "Bagaimana kalau besok pagi kita main sepak bola?",
       "ja": "明日の朝サッカーをしに行きませんか？",
       "py": "Míngtiān zǎoshàng wǒmen qù tī zúqiú, zěnmeyàng?",
       "a": "3dc14da6b776"
      },
      "ans": {
       "zh": "好啊！我們一起去。",
       "en": "Great! Let's go together.",
       "id": "Oke! Kita pergi bersama.",
       "ja": "いいですね！一緒に行きましょう。",
       "py": "Hǎo a! Wǒmen yìqǐ qù.",
       "a": "8f4ac410062c"
      }
     }
    ],
    "full": "speak_L3_1.mp3"
   }
  ],
