  "n": 8,
  "zh": "坐火車去臺南",
  "en": "Taking a Train to Tainan",
  "topic": "Transportation",
  "speak": [
   {
    "title": "會話練習 Speaking practice",
    "items": [
     {
      "q": {
       "zh": "你常坐什麼去學校？",
       "en": "How do you usually get to school?",
       "id": "Biasanya kamu naik apa ke sekolah?",
       "ja": "学校へはよく何で行きますか？",
       "py": "Nǐ cháng zuò shénme qù xuéxiào?",
       "a": "2bce00d804bc"
      },
      "ans": {
       "zh": "我常坐捷運去學校，比較快。",
       "en": "I usually take the MRT to school. It's faster.",
       "id": "Saya biasanya naik MRT ke sekolah, lebih cepat.",
       "ja": "よくMRTで学校へ行きます。速いからです。",
       "py": "Wǒ cháng zuò jiéyùn qù xuéxiào, bǐjiào kuài.",
       "a": "80c5178a61aa"
      }
     },
     {
      "q": {
       "zh": "坐火車去臺南要多久？",
       "en": "How long does it take to go to Tainan by train?",
       "id": "Naik kereta ke Tainan berapa lama?",
       "ja": "電車で台南まで行くとどのくらいかかりますか？",
       "py": "Zuò huǒchē qù Táinán yào duō jiǔ?",
       "a": "0c6e0a1b79d9"
      },
      "ans": {
       "zh": "坐火車要四個多鐘頭，坐高鐵比較快。",
       "en": "By train it takes over four hours. The High Speed Rail is faster.",
       "id": "Naik kereta lebih dari empat jam, naik kereta cepat lebih cepat.",
       "ja": "電車だと4時間以上かかります。高鉄のほうが速いです。",
       "py": "Zuò huǒchē yào sì ge duō zhōngtóu, zuò gāotiě bǐjiào kuài.",
       "a": "10855d3cbee8"
      }
     },
     {
      "q": {
       "zh": "你覺得高鐵怎麼樣？",
       "en": "What do you think of the High Speed Rail?",
       "id": "Menurutmu kereta cepat bagaimana?",
       "ja": "高鉄はどうだと思いますか？",
       "py": "Nǐ juéde gāotiě zěnmeyàng?",
       "a": "3e9b524f3f5f"
      },
      "ans": {
       "zh": "高鐵又快又舒服，可是車票有一點貴。",
       "en": "The HSR is both fast and comfortable, but the tickets are a bit expensive.",
       "id": "Kereta cepat itu cepat dan nyaman, tapi tiketnya agak mahal.",
       "ja": "高鉄は速くて快適ですが、切符が少し高いです。",
       "py": "Gāotiě yòu kuài yòu shūfú, kěshì chēpiào yǒu yìdiǎn guì.",
       "a": "0e6730afcca7"
      }
     },
     {
      "q": {
       "zh": "你在哪裡買車票？",
       "en": "Where do you buy tickets?",
       "id": "Kamu beli tiket di mana?",
       "ja": "切符はどこで買いますか？",
       "py": "Nǐ zài nǎlǐ mǎi chēpiào?",
       "a": "ca91f620bc96"
      },
      "ans": {
       "zh": "我在網路上或是便利商店買車票。",
       "en": "I buy tickets online or at convenience stores.",
       "id": "Saya beli tiket online atau di minimarket.",
       "ja": "ネットかコンビニで切符を買います。",
       "py": "Wǒ zài wǎnglù shàng huòshì biànlì shāngdiàn mǎi chēpiào.",
       "a": "2ac928c08db7"
      }
     },
     {
      "q": {
       "zh": "週末你想跟誰去玩？",
       "en": "Who do you want to go out with on the weekend?",
       "id": "Akhir pekan kamu mau jalan-jalan dengan siapa?",
       "ja": "週末は誰と遊びに行きたいですか？",
       "py": "Zhōumò nǐ xiǎng gēn shéi qù wán?",
       "a": "14fa178ba212"
      },
      "ans": {
       "zh": "週末我想跟同學去臺南玩。",
       "en": "On the weekend I want to go to Tainan with my classmates.",
       "id": "Akhir pekan saya mau jalan-jalan ke Tainan dengan teman sekelas.",
       "ja": "週末はクラスメートと台南へ遊びに行きたいです。",
       "py": "Zhōumò wǒ xiǎng gēn tóngxué qù Táinán wán.",
       "a": "7547f78a58eb"
      }
     },
     {
      "q": {
       "zh": "騎機車比坐公車快嗎？",
       "en": "Is riding a scooter faster than taking the bus?",
       "id": "Naik motor lebih cepat daripada naik bus?",
       "ja": "バイクはバスより速いですか？",
       "py": "Qí jīchē bǐ zuò gōngchē kuài ma?",
       "a": "444f8767ca36"
      },
      "ans": {
       "zh": "差不多，可是騎機車比較方便。",
       "en": "About the same, but a scooter is more convenient.",
       "id": "Kurang lebih sama, tapi naik motor lebih praktis.",
       "ja": "だいたい同じですが、バイクのほうが便利です。",
       "py": "Chābùduō, kěshì qí jīchē bǐjiào fāngbiàn.",
       "a": "54d774e9e1e0"
      }
     },
     {
      "q": {
       "zh": "你想去參觀故宮博物院嗎？",
       "en": "Do you want to visit the National Palace Museum?",
       "id": "Kamu mau mengunjungi Museum Istana Nasional?",
       "ja": "故宮博物院を見学したいですか？",
       "py": "Nǐ xiǎng qù cānguān Gùgōng Bówùyuàn ma?",
       "a": "f913eb182e9f"
      },
      "ans": {
       "zh": "想，聽說那裡有很多中國古代的東西。",
       "en": "Yes, I've heard there are many ancient Chinese things there.",
       "id": "Mau, katanya di sana ada banyak benda Tiongkok kuno.",
       "ja": "はい、あそこには中国の古代の物がたくさんあるそうです。",
       "py": "Xiǎng, tīngshuō nàlǐ yǒu hěn duō Zhōngguó gǔdài de dōngxi.",
       "a": "d17454de2083"
      }
     },
     {
      "q": {
       "zh": "到故宮有沒有捷運？",
       "en": "Is there an MRT to the Palace Museum?",
       "id": "Apakah ada MRT ke Museum Istana?",
       "ja": "故宮までMRTはありますか？",
       "py": "Dào Gùgōng yǒu méi yǒu jiéyùn?",
       "a": "c4093f4079f3"
      },
      "ans": {
       "zh": "沒有，可以坐公車或是計程車去。",
       "en": "No. You can take a bus or a taxi.",
       "id": "Tidak ada, bisa naik bus atau taksi.",
       "ja": "ありません。バスかタクシーで行けます。",
       "py": "Méi yǒu, kěyǐ zuò gōngchē huòshì jìchéngchē qù.",
       "a": "06eb875b74dd"
      }
     }
    ],
    "full": "speak_L8_1.mp3"
   }
  ],
