  "n": 9,
  "zh": "放假去哪裡玩？",
  "en": "Where Will You Go for the Holidays?",
  "topic": "Travel & Holidays",
  "speak": [
   {
    "title": "會話練習 Speaking practice",
    "items": [
     {
      "q": {
       "zh": "放假的時候，你常做什麼？",
       "en": "What do you usually do on holidays?",
       "id": "Waktu libur, kamu biasanya melakukan apa?",
       "ja": "休みのとき、よく何をしますか？",
       "py": "Fàngjià de shíhòu, nǐ cháng zuò shénme?",
       "a": "c832f3da3211"
      },
      "ans": {
       "zh": "有時候在家看電視，有時候出去玩。",
       "en": "Sometimes I watch TV at home, sometimes I go out.",
       "id": "Kadang di rumah menonton TV, kadang keluar jalan-jalan.",
       "ja": "家でテレビを見るときもあれば、遊びに出かけるときもあります。",
       "py": "Yǒu shíhòu zài jiā kàn diànshì, yǒu shíhòu chūqù wán.",
       "a": "892763734208"
      }
     },
     {
      "q": {
       "zh": "下個星期你打算做什麼？",
       "en": "What do you plan to do next week?",
       "id": "Minggu depan kamu berencana melakukan apa?",
       "ja": "来週は何をするつもりですか？",
       "py": "Xià ge xīngqí nǐ dǎsuàn zuò shénme?",
       "a": "375a0b8c20d1"
      },
      "ans": {
       "zh": "下個星期我打算跟朋友去臺東旅行。",
       "en": "Next week I plan to travel to Taitung with friends.",
       "id": "Minggu depan saya berencana jalan-jalan ke Taitung dengan teman.",
       "ja": "来週は友達と台東へ旅行するつもりです。",
       "py": "Xià ge xīngqí wǒ dǎsuàn gēn péngyǒu qù Táidōng lǚxíng.",
       "a": "0cb9ee900632"
      }
     },
     {
      "q": {
       "zh": "你們放幾天的假？",
       "en": "How many days off do you have?",
       "id": "Kalian libur berapa hari?",
       "ja": "休みは何日ありますか？",
       "py": "Nǐmen fàng jǐ tiān de jiǎ?",
       "a": "062da414bec1"
      },
      "ans": {
       "zh": "我們放五天的假。",
       "en": "We have five days off.",
       "id": "Kami libur lima hari.",
       "ja": "5日間休みです。",
       "py": "Wǒmen fàng wǔ tiān de jiǎ.",
       "a": "8dd429683ed2"
      }
     },
     {
      "q": {
       "zh": "放假的時候，你要回國嗎？",
       "en": "Are you going back to your country during the holiday?",
       "id": "Waktu libur, kamu mau pulang ke negaramu?",
       "ja": "休みのとき、国へ帰りますか？",
       "py": "Fàngjià de shíhòu, nǐ yào huíguó ma?",
       "a": "69bd742b2eac"
      },
      "ans": {
       "zh": "不，我打算在臺灣學中文。",
       "en": "No, I plan to study Chinese in Taiwan.",
       "id": "Tidak, saya berencana belajar bahasa Mandarin di Taiwan.",
       "ja": "いいえ、台湾で中国語を勉強するつもりです。",
       "py": "Bù, wǒ dǎsuàn zài Táiwān xué Zhōngwén.",
       "a": "329b3da5b0f0"
      }
     },
     {
      "q": {
       "zh": "朋友來臺灣，你想帶他去哪裡玩？",
       "en": "When a friend comes to Taiwan, where will you take them?",
       "id": "Kalau teman datang ke Taiwan, kamu mau mengajaknya ke mana?",
       "ja": "友達が台湾に来たら、どこへ連れて行きたいですか？",
       "py": "Péngyǒu lái Táiwān, nǐ xiǎng dài tā qù nǎlǐ wán?",
       "a": "d85497b02764"
      },
      "ans": {
       "zh": "我想帶他去逛夜市。",
       "en": "I want to take them to stroll around a night market.",
       "id": "Saya mau mengajaknya jalan-jalan ke pasar malam.",
       "ja": "夜市をぶらぶらしに連れて行きたいです。",
       "py": "Wǒ xiǎng dài tā qù guàng yèshì.",
       "a": "b940992260ba"
      }
     },
     {
      "q": {
       "zh": "你有什麼建議？到哪裡喝茶比較好？",
       "en": "Do you have any suggestions? Where's a good place to have tea?",
       "id": "Ada saran? Minum teh di mana yang lebih bagus?",
       "ja": "何かおすすめはありますか？どこでお茶を飲むのがいいですか？",
       "py": "Nǐ yǒu shénme jiànyì? Dào nǎlǐ hē chá bǐjiào hǎo?",
       "a": "3b89183c0805"
      },
      "ans": {
       "zh": "你們可以去貓空，那裡的風景很美。",
       "en": "You can go to Maokong. The scenery there is beautiful.",
       "id": "Kalian bisa ke Maokong, pemandangan di sana indah.",
       "ja": "猫空に行くといいですよ。景色がきれいです。",
       "py": "Nǐmen kěyǐ qù Māokōng, nàlǐ de fēngjǐng hěn měi.",
       "a": "3c94ebdc92c6"
      }
     },
     {
      "q": {
       "zh": "今天幾月幾號？",
       "en": "What's the date today?",
       "id": "Hari ini tanggal berapa bulan apa?",
       "ja": "今日は何月何日ですか？",
       "py": "Jīntiān jǐ yuè jǐ hào?",
       "a": "d677aa0089ec"
      },
      "ans": {
       "zh": "今天十月二十八號。",
       "en": "Today is October 28th.",
       "id": "Hari ini tanggal 28 Oktober.",
       "ja": "今日は10月28日です。",
       "py": "Jīntiān shí yuè èrshí bā hào.",
       "a": "c2f94086fa0e"
      }
     },
     {
      "q": {
       "zh": "要是你有空，想做什麼？",
       "en": "If you are free, what do you want to do?",
       "id": "Kalau kamu ada waktu, mau melakukan apa?",
       "ja": "もし暇だったら、何をしたいですか？",
       "py": "Yàoshì nǐ yǒu kòng, xiǎng zuò shénme?",
       "a": "a747c111e4ed"
      },
      "ans": {
       "zh": "要是我有空，就去旅行。",
       "en": "If I'm free, I'll go traveling.",
       "id": "Kalau saya ada waktu, saya akan bepergian.",
       "ja": "暇があったら、旅行に行きます。",
       "py": "Yàoshì wǒ yǒu kòng, jiù qù lǚxíng.",
       "a": "d772377d4292"
      }
     }
    ],
    "full": "speak_L9_1.mp3"
   }
  ],
