  "n": 10,
  "zh": "臺灣的水果很好吃",
  "en": "The Fruit in Taiwan Tastes Really Good",
  "topic": "Fruit & Describing People",
  "speak": [
   {
    "title": "會話練習 Speaking practice",
    "items": [
     {
      "q": {
       "zh": "你喜歡吃什麼水果？",
       "en": "What fruit do you like to eat?",
       "id": "Kamu suka makan buah apa?",
       "ja": "どんな果物が好きですか？",
       "py": "Nǐ xǐhuān chī shénme shuǐguǒ?",
       "a": "d7d5ae8ffa4e"
      },
      "ans": {
       "zh": "我最喜歡吃芒果，又香又甜。",
       "en": "I like mangoes best. They're fragrant and sweet.",
       "id": "Saya paling suka mangga, harum dan manis.",
       "ja": "マンゴーが一番好きです。いい香りで甘いです。",
       "py": "Wǒ zuì xǐhuān chī mángguǒ, yòu xiāng yòu tián.",
       "a": "f1cf14002811"
      }
     },
     {
      "q": {
       "zh": "西瓜是紅色的嗎？",
       "en": "Is watermelon red?",
       "id": "Apakah semangka berwarna merah?",
       "ja": "スイカは赤いですか？",
       "py": "Xīguā shì hóngsè de ma?",
       "a": "300a09d2aab5"
      },
      "ans": {
       "zh": "對，西瓜是紅色的，很甜。",
       "en": "Yes, watermelon is red and very sweet.",
       "id": "Ya, semangka berwarna merah, manis sekali.",
       "ja": "はい、スイカは赤くて、とても甘いです。",
       "py": "Duì, xīguā shì hóngsè de, hěn tián.",
       "a": "5a113792d38f"
      }
     },
     {
      "q": {
       "zh": "你以前喜歡吃水果嗎？",
       "en": "Did you like to eat fruit before?",
       "id": "Dulu kamu suka makan buah?",
       "ja": "以前は果物が好きでしたか？",
       "py": "Nǐ yǐqián xǐhuān chī shuǐguǒ ma?",
       "a": "49cdc5b87c93"
      },
      "ans": {
       "zh": "我以前不喜歡，現在很喜歡了。",
       "en": "I didn't before, but now I like it very much.",
       "id": "Dulu tidak suka, sekarang suka sekali.",
       "ja": "以前は好きじゃなかったけど、今は大好きです。",
       "py": "Wǒ yǐqián bù xǐhuān, xiànzài hěn xǐhuān le.",
       "a": "1ed33326ece1"
      }
     },
     {
      "q": {
       "zh": "你今天穿藍色的衣服嗎？",
       "en": "Are you wearing blue clothes today?",
       "id": "Hari ini kamu memakai baju biru?",
       "ja": "今日は青い服を着ていますか？",
       "py": "Nǐ jīntiān chuān lánsè de yīfú ma?",
       "a": "9ba6615bc1d7"
      },
      "ans": {
       "zh": "不是，我今天穿黃色的衣服。",
       "en": "No, I'm wearing yellow clothes today.",
       "id": "Bukan, hari ini saya memakai baju kuning.",
       "ja": "いいえ、今日は黄色い服を着ています。",
       "py": "Bú shì, wǒ jīntiān chuān huángsè de yīfú.",
       "a": "ec4742c8fc4a"
      }
     },
     {
      "q": {
       "zh": "你家人誰最高？誰最矮？",
       "en": "Who is the tallest in your family? Who is the shortest?",
       "id": "Di keluargamu siapa yang paling tinggi? Siapa yang paling pendek?",
       "ja": "家族で誰が一番背が高いですか？誰が一番低いですか？",
       "py": "Nǐ jiārén shéi zuì gāo? Shéi zuì ǎi?",
       "a": "f1deacb81b3b"
      },
      "ans": {
       "zh": "我弟弟最高，我媽媽最矮。",
       "en": "My younger brother is the tallest, and my mom is the shortest.",
       "id": "Adik laki-laki saya paling tinggi, ibu saya paling pendek.",
       "ja": "弟が一番高くて、母が一番低いです。",
       "py": "Wǒ dìdi zuì gāo, wǒ māma zuì ǎi.",
       "a": "92b65c28456e"
      }
     },
     {
      "q": {
       "zh": "上個月你去哪裡玩？好玩嗎？",
       "en": "Where did you go last month? Was it fun?",
       "id": "Bulan lalu kamu jalan-jalan ke mana? Seru tidak?",
       "ja": "先月はどこへ遊びに行きましたか？楽しかったですか？",
       "py": "Shàng ge yuè nǐ qù nǎlǐ wán? Hǎowán ma?",
       "a": "07e6df3c16bc"
      },
      "ans": {
       "zh": "上個月我去花蓮玩，玩得很開心。",
       "en": "Last month I went to Hualien and had a great time.",
       "id": "Bulan lalu saya ke Hualien, senang sekali.",
       "ja": "先月は花蓮へ遊びに行って、とても楽しかったです。",
       "py": "Shàng ge yuè wǒ qù Huālián wán, wán de hěn kāixīn.",
       "a": "fdff8123059e"
      }
     },
     {
      "q": {
       "zh": "那家旅館怎麼樣？乾淨嗎？",
       "en": "How was the hotel? Was it clean?",
       "id": "Penginapannya bagaimana? Bersih?",
       "ja": "その旅館はどうでしたか？きれいでしたか？",
       "py": "Nàjiā lǚguǎn zěnmeyàng? Gānjìng ma?",
       "a": "8fbf664288a3"
      },
      "ans": {
       "zh": "很乾淨，從窗戶往外看，是藍色的大海。",
       "en": "Very clean. Looking out the window, you see the blue sea.",
       "id": "Sangat bersih, dari jendela terlihat laut biru.",
       "ja": "とてもきれいでした。窓から外を見ると青い海でした。",
       "py": "Hěn gānjìng, cóng chuānghù wǎng wài kàn, shì lánsè de dà hǎi.",
       "a": "0916cd049bf5"
      }
     },
     {
      "q": {
       "zh": "這些照片是誰拍的？",
       "en": "Who took these photos?",
       "id": "Foto-foto ini siapa yang mengambil?",
       "ja": "これらの写真は誰が撮りましたか？",
       "py": "Zhèxiē zhàopiàn shì shéi pāi de?",
       "a": "d94fd5ead9f5"
      },
      "ans": {
       "zh": "這些照片是我拍的。",
       "en": "I took these photos.",
       "id": "Foto-foto ini saya yang mengambil.",
       "ja": "これらの写真は私が撮りました。",
       "py": "Zhèxiē zhàopiàn shì wǒ pāi de.",
       "a": "563b1ff6be1b"
      }
     }
    ],
    "full": "speak_L10_1.mp3"
   }
  ],
