  "n": 11,
  "zh": "我要租房子",
  "en": "I Would Like to Rent a Place",
  "topic": "Renting a Room",
  "speak": [
   {
    "title": "會話練習 Speaking practice",
    "items": [
     {
      "q": {
       "zh": "你想租套房嗎？",
       "en": "Do you want to rent a room with its own bathroom?",
       "id": "Kamu mau menyewa kamar dengan kamar mandi dalam?",
       "ja": "バス付きの部屋を借りたいですか？",
       "py": "Nǐ xiǎng zū tàofáng ma?",
       "a": "ffd6d829ae63"
      },
      "ans": {
       "zh": "想，我想租有浴室的套房。",
       "en": "Yes, I want to rent a suite with a bathroom.",
       "id": "Mau, saya mau menyewa kamar yang ada kamar mandinya.",
       "ja": "はい、浴室付きの部屋を借りたいです。",
       "py": "Xiǎng, wǒ xiǎng zū yǒu yùshì de tàofáng.",
       "a": "a368e28e76c0"
      }
     },
     {
      "q": {
       "zh": "你家附近有超市嗎？",
       "en": "Is there a supermarket near your home?",
       "id": "Di dekat rumahmu ada supermarket?",
       "ja": "家の近くにスーパーはありますか？",
       "py": "Nǐ jiā fùjìn yǒu chāoshì ma?",
       "a": "91c14e11051a"
      },
      "ans": {
       "zh": "有，走路五分鐘就到了。",
       "en": "Yes, it's just a five-minute walk.",
       "id": "Ada, jalan kaki lima menit saja sudah sampai.",
       "ja": "あります。歩いて5分で着きます。",
       "py": "Yǒu, zǒulù wǔ fēnzhōng jiù dào le.",
       "a": "4008637f0948"
      }
     },
     {
      "q": {
       "zh": "你的房間裡面可以上網嗎？",
       "en": "Can you go online in your room?",
       "id": "Di dalam kamarmu bisa pakai internet?",
       "ja": "部屋の中でネットは使えますか？",
       "py": "Nǐ de fángjiān lǐmiàn kěyǐ shàngwǎng ma?",
       "a": "6dfb3035ce19"
      },
      "ans": {
       "zh": "可以，房間裡面可以上網。",
       "en": "Yes, I can go online in my room.",
       "id": "Bisa, di dalam kamar bisa pakai internet.",
       "ja": "はい、部屋の中でネットが使えます。",
       "py": "Kěyǐ, fángjiān lǐmiàn kěyǐ shàngwǎng.",
       "a": "0c386a355240"
      }
     },
     {
      "q": {
       "zh": "你的房東姓什麼？他怎麼樣？",
       "en": "What is your landlord's surname? What's he like?",
       "id": "Pemilik rumah sewamu nama keluarganya apa? Orangnya bagaimana?",
       "ja": "大家さんの名字は何ですか？どんな人ですか？",
       "py": "Nǐ de fángdōng xìng shénme? Tā zěnmeyàng?",
       "a": "6e23ea8bb5d8"
      },
      "ans": {
       "zh": "我的房東姓林，他很不錯。",
       "en": "My landlord's surname is Lin. He's very nice.",
       "id": "Pemilik rumah saya bernama keluarga Lin, dia baik sekali.",
       "ja": "大家さんは林さんで、とてもいい人です。",
       "py": "Wǒ de fángdōng xìng Lín, tā hěn búcuò.",
       "a": "2b52b55c3452"
      }
     },
     {
      "q": {
       "zh": "你一個月的房租多少錢？",
       "en": "How much is your rent per month?",
       "id": "Uang sewamu sebulan berapa?",
       "ja": "家賃は月いくらですか？",
       "py": "Nǐ yí ge yuè de fángzū duōshǎo qián?",
       "a": "f6cfd385a837"
      },
      "ans": {
       "zh": "我一個月的房租八千塊。",
       "en": "My rent is eight thousand dollars a month.",
       "id": "Uang sewa saya delapan ribu dolar sebulan.",
       "ja": "家賃は月8千元です。",
       "py": "Wǒ yí ge yuè de fángzū bā qiān kuài.",
       "a": "1adfaf7f7536"
      }
     },
     {
      "q": {
       "zh": "你住在這裡習慣了嗎？",
       "en": "Have you gotten used to living here?",
       "id": "Kamu sudah terbiasa tinggal di sini?",
       "ja": "ここでの生活に慣れましたか？",
       "py": "Nǐ zhù zài zhèlǐ xíguàn le ma?",
       "a": "e3fa68af4f6c"
      },
      "ans": {
       "zh": "習慣了，這裡很方便。",
       "en": "Yes, I'm used to it. It's very convenient here.",
       "id": "Sudah terbiasa, di sini sangat praktis.",
       "ja": "慣れました。ここはとても便利です。",
       "py": "Xíguàn le, zhèlǐ hěn fāngbiàn.",
       "a": "614e4ae2ac87"
      }
     },
     {
      "q": {
       "zh": "今天晚上你有空嗎？",
       "en": "Are you free tonight?",
       "id": "Malam ini kamu ada waktu?",
       "ja": "今晩は暇ですか？",
       "py": "Jīntiān wǎnshàng nǐ yǒu kòng ma?",
       "a": "809ef9e638d9"
      },
      "ans": {
       "zh": "不好意思，今天晚上我有事。",
       "en": "Sorry, I have something to do tonight.",
       "id": "Maaf, malam ini saya ada urusan.",
       "ja": "すみません、今晩は用事があります。",
       "py": "Bùhǎo yìsi, jīntiān wǎnshàng wǒ yǒu shì.",
       "a": "931092d53a24"
      }
     },
     {
      "q": {
       "zh": "你家的熱水器有問題嗎？",
       "en": "Is there a problem with your water heater?",
       "id": "Apakah pemanas air di rumahmu bermasalah?",
       "ja": "家の給湯器に問題はありますか？",
       "py": "Nǐ jiā de rèshuǐqì yǒu wèntí ma?",
       "a": "189d62efe9f4"
      },
      "ans": {
       "zh": "熱水器的水好像不熱，我得打電話給房東。",
       "en": "The water doesn't seem hot. I have to call the landlord.",
       "id": "Air dari pemanasnya sepertinya tidak panas, saya harus menelepon pemilik rumah.",
       "ja": "お湯が熱くないみたいなので、大家さんに電話しなければなりません。",
       "py": "Rèshuǐqì de shuǐ hǎoxiàng bú rè, wǒ děi dǎ diànhuà gěi fángdōng.",
       "a": "f95b56880aba"
      }
     }
    ],
    "full": "speak_L11_1.mp3"
   }
  ],
