  "n": 12,
  "zh": "你在臺灣學多久的中文？",
  "en": "How Long Will You Be Studying Chinese in Taiwan?",
  "topic": "Study & Work Plans",
  "speak": [
   {
    "title": "會話練習 Speaking practice",
    "items": [
     {
      "q": {
       "zh": "你計畫在臺灣學多久的中文？",
       "en": "How long do you plan to study Chinese in Taiwan?",
       "id": "Berapa lama kamu berencana belajar bahasa Mandarin di Taiwan?",
       "ja": "台湾でどのくらい中国語を勉強する予定ですか？",
       "py": "Nǐ jìhuà zài Táiwān xué duō jiǔ de Zhōngwén?",
       "a": "222542863295"
      },
      "ans": {
       "zh": "我計畫學一年。",
       "en": "I plan to study for one year.",
       "id": "Saya berencana belajar satu tahun.",
       "ja": "1年勉強する予定です。",
       "py": "Wǒ jìhuà xué yì nián.",
       "a": "a64f05d4217e"
      }
     },
     {
      "q": {
       "zh": "你的學費是誰付的？",
       "en": "Who pays your tuition?",
       "id": "Biaya kuliahmu siapa yang bayar?",
       "ja": "学費は誰が払っていますか？",
       "py": "Nǐ de xuéfèi shì shéi fù de?",
       "a": "667355ebe2bc"
      },
      "ans": {
       "zh": "我的學費是我自己付的。",
       "en": "I pay my tuition myself.",
       "id": "Biaya kuliah saya, saya bayar sendiri.",
       "ja": "学費は自分で払っています。",
       "py": "Wǒ de xuéfèi shì wǒ zìjǐ fù de.",
       "a": "618ed334cb17"
      }
     },
     {
      "q": {
       "zh": "你有獎學金嗎？",
       "en": "Do you have a scholarship?",
       "id": "Kamu dapat beasiswa?",
       "ja": "奨学金はありますか？",
       "py": "Nǐ yǒu jiǎngxuéjīn ma?",
       "a": "dd921fc93425"
      },
      "ans": {
       "zh": "沒有，不過我希望以後有。",
       "en": "No, but I hope to have one in the future.",
       "id": "Tidak, tapi saya berharap nanti dapat.",
       "ja": "ありませんが、将来もらえるといいなと思っています。",
       "py": "Méi yǒu, búguò wǒ xīwàng yǐhòu yǒu.",
       "a": "097c19896bda"
      }
     },
     {
      "q": {
       "zh": "你以後想做什麼工作？",
       "en": "What job do you want to do in the future?",
       "id": "Nanti kamu ingin bekerja apa?",
       "ja": "将来どんな仕事がしたいですか？",
       "py": "Nǐ yǐhòu xiǎng zuò shénme gōngzuò?",
       "a": "17feae005ce0"
      },
      "ans": {
       "zh": "我以後想找個有機會說中文的工作。",
       "en": "In the future I want a job where I can speak Chinese.",
       "id": "Nanti saya ingin mencari pekerjaan yang ada kesempatan berbahasa Mandarin.",
       "ja": "将来、中国語を話す機会がある仕事を探したいです。",
       "py": "Wǒ yǐhòu xiǎng zhǎo ge yǒu jīhuì shuō Zhōngwén de gōngzuò.",
       "a": "1d149defbf77"
      }
     },
     {
      "q": {
       "zh": "你是什麼時候來臺灣的？",
       "en": "When did you come to Taiwan?",
       "id": "Kapan kamu datang ke Taiwan?",
       "ja": "いつ台湾に来ましたか？",
       "py": "Nǐ shì shénme shíhòu lái Táiwān de?",
       "a": "52110b0ca8f4"
      },
      "ans": {
       "zh": "我是去年來臺灣的。",
       "en": "I came to Taiwan last year.",
       "id": "Saya datang ke Taiwan tahun lalu.",
       "ja": "去年台湾に来ました。",
       "py": "Wǒ shì qùnián lái Táiwān de.",
       "a": "18e70689ac9d"
      }
     },
     {
      "q": {
       "zh": "你又要上班又要念書嗎？",
       "en": "Do you have to both work and study?",
       "id": "Apakah kamu harus bekerja dan juga belajar?",
       "ja": "仕事も勉強もしなければなりませんか？",
       "py": "Nǐ yòu yào shàngbān yòu yào niànshū ma?",
       "a": "582995ab96fa"
      },
      "ans": {
       "zh": "對，我又要上班又要念書，真的很累。",
       "en": "Yes, I have to both work and study. It's really tiring.",
       "id": "Ya, saya harus bekerja dan belajar, benar-benar capek.",
       "ja": "はい、仕事も勉強もしなければならなくて、本当に疲れます。",
       "py": "Duì, wǒ yòu yào shàngbān yòu yào niànshū, zhēnde hěn lèi.",
       "a": "998c3718f422"
      }
     },
     {
      "q": {
       "zh": "這樣的工作在你們國家好找嗎？",
       "en": "Is that kind of job easy to find in your country?",
       "id": "Pekerjaan seperti itu mudah dicari di negaramu?",
       "ja": "そういう仕事はあなたの国で見つけやすいですか？",
       "py": "Zhèyàng de gōngzuò zài nǐmen guójiā hǎo zhǎo ma?",
       "a": "9e0c01c98e06"
      },
      "ans": {
       "zh": "不太好找，可是我想試試看。",
       "en": "Not very easy, but I want to give it a try.",
       "id": "Tidak terlalu mudah, tapi saya mau mencobanya.",
       "ja": "あまり見つけやすくないですが、やってみたいです。",
       "py": "Bú tài hǎo zhǎo, kěshì wǒ xiǎng shìshìkàn.",
       "a": "31ad81d1b2b3"
      }
     },
     {
      "q": {
       "zh": "你先學中文，再做什麼？",
       "en": "You'll study Chinese first, and then what?",
       "id": "Kamu belajar bahasa Mandarin dulu, lalu apa?",
       "ja": "まず中国語を勉強して、それから何をしますか？",
       "py": "Nǐ xiān xué Zhōngwén, zài zuò shénme?",
       "a": "156b6e84ca02"
      },
      "ans": {
       "zh": "我先學中文，再念大學。",
       "en": "First I'll study Chinese, then go to university.",
       "id": "Saya belajar bahasa Mandarin dulu, lalu kuliah.",
       "ja": "まず中国語を勉強して、それから大学に行きます。",
       "py": "Wǒ xiān xué Zhōngwén, zài niàn dàxué.",
       "a": "ac17371de90a"
      }
     }
    ],
    "full": "speak_L12_1.mp3"
   }
  ],
