  "n": 14,
  "zh": "天氣這麼冷！",
  "en": "It's So Cold!",
  "topic": "Weather & Seasons",
  "speak": [
   {
    "title": "會話練習 Speaking practice",
    "items": [
     {
      "q": {
       "zh": "今天天氣怎麼樣？",
       "en": "How is the weather today?",
       "id": "Bagaimana cuaca hari ini?",
       "ja": "今日の天気はどうですか？",
       "py": "Jīntiān tiānqì zěnmeyàng?",
       "a": "035af4b8bf37"
      },
      "ans": {
       "zh": "今天天氣很好，不太冷。",
       "en": "The weather is nice today, not too cold.",
       "id": "Cuaca hari ini bagus, tidak terlalu dingin.",
       "ja": "今日は天気がよくて、あまり寒くないです。",
       "py": "Jīntiān tiānqì hěn hǎo, bú tài lěng.",
       "a": "407d41f0a9d0"
      }
     },
     {
      "q": {
       "zh": "你比較喜歡春天還是秋天？",
       "en": "Do you prefer spring or autumn?",
       "id": "Kamu lebih suka musim semi atau musim gugur?",
       "ja": "春と秋、どちらが好きですか？",
       "py": "Nǐ bǐjiào xǐhuān chūntiān háishì qiūtiān?",
       "a": "b3c1a8726cd8"
      },
      "ans": {
       "zh": "我比較喜歡秋天，可以看紅葉。",
       "en": "I prefer autumn. You can see the red leaves.",
       "id": "Saya lebih suka musim gugur, bisa melihat daun merah.",
       "ja": "秋のほうが好きです。紅葉が見られるからです。",
       "py": "Wǒ bǐjiào xǐhuān qiūtiān, kěyǐ kàn hóngyè.",
       "a": "15098a13531d"
      }
     },
     {
      "q": {
       "zh": "你們國家會下雪嗎？",
       "en": "Does it snow in your country?",
       "id": "Apakah di negaramu turun salju?",
       "ja": "あなたの国では雪が降りますか？",
       "py": "Nǐmen guójiā huì xiàxuě ma?",
       "a": "d057e1346195"
      },
      "ans": {
       "zh": "我們國家不會下雪，冬天也不冷。",
       "en": "It doesn't snow in my country, and winter isn't cold either.",
       "id": "Di negara saya tidak turun salju, musim dinginnya juga tidak dingin.",
       "ja": "私の国では雪は降りません。冬も寒くありません。",
       "py": "Wǒmen guójiā bú huì xiàxuě, dōngtiān yě bù lěng.",
       "a": "06f719aad001"
      }
     },
     {
      "q": {
       "zh": "你會滑雪嗎？",
       "en": "Can you ski?",
       "id": "Kamu bisa main ski?",
       "ja": "スキーはできますか？",
       "py": "Nǐ huì huáxuě ma?",
       "a": "edf8bd80c992"
      },
      "ans": {
       "zh": "不會，可是我很想學。",
       "en": "No, but I really want to learn.",
       "id": "Tidak bisa, tapi saya sangat ingin belajar.",
       "ja": "できませんが、とても習いたいです。",
       "py": "Bú huì, kěshì wǒ hěn xiǎng xué.",
       "a": "a2bca14d59c1"
      }
     },
     {
      "q": {
       "zh": "你怕冷還是怕熱？",
       "en": "Do you mind the cold or the heat more?",
       "id": "Kamu lebih tidak tahan dingin atau panas?",
       "ja": "寒いのと暑いの、どちらが苦手ですか？",
       "py": "Nǐ pà lěng háishì pà rè?",
       "a": "facd19f71d8b"
      },
      "ans": {
       "zh": "我怕熱，我比較喜歡冬天。",
       "en": "I don't like the heat. I prefer winter.",
       "id": "Saya tidak tahan panas, saya lebih suka musim dingin.",
       "ja": "暑いのが苦手です。冬のほうが好きです。",
       "py": "Wǒ pà rè, wǒ bǐjiào xǐhuān dōngtiān.",
       "a": "d999357606fd"
      }
     },
     {
      "q": {
       "zh": "下雨的時候，你常帶傘嗎？",
       "en": "Do you usually bring an umbrella when it rains?",
       "id": "Saat hujan, kamu biasanya bawa payung?",
       "ja": "雨のとき、よく傘を持っていきますか？",
       "py": "Xiàyǔ de shíhòu, nǐ cháng dài sǎn ma?",
       "a": "dc436fa6f424"
      },
      "ans": {
       "zh": "我常忘了帶傘。",
       "en": "I often forget to bring an umbrella.",
       "id": "Saya sering lupa bawa payung.",
       "ja": "よく傘を忘れます。",
       "py": "Wǒ cháng wàngle dài sǎn.",
       "a": "a8878bd44ff5"
      }
     },
     {
      "q": {
       "zh": "你在臺灣住了多久了？",
       "en": "How long have you lived in Taiwan?",
       "id": "Sudah berapa lama kamu tinggal di Taiwan?",
       "ja": "台湾に住んでどのくらいになりますか？",
       "py": "Nǐ zài Táiwān zhù le duō jiǔ le?",
       "a": "f515728b9e1a"
      },
      "ans": {
       "zh": "我在臺灣住了半年多了。",
       "en": "I've lived in Taiwan for more than half a year.",
       "id": "Saya sudah tinggal di Taiwan lebih dari setengah tahun.",
       "ja": "台湾に住んで半年以上になります。",
       "py": "Wǒ zài Táiwān zhù le bàn nián duō le.",
       "a": "50b3ebd09ee4"
      }
     },
     {
      "q": {
       "zh": "你想家嗎？",
       "en": "Do you miss home?",
       "id": "Kamu rindu rumah?",
       "ja": "ホームシックですか？",
       "py": "Nǐ xiǎng jiā ma?",
       "a": "d2a8802fefd9"
      },
      "ans": {
       "zh": "有一點想家。",
       "en": "I'm a little homesick.",
       "id": "Agak rindu rumah.",
       "ja": "少しホームシックです。",
       "py": "Yǒu yìdiǎn xiǎng jiā.",
       "a": "992ec5524c58"
      }
     }
    ],
    "full": "speak_L14_1.mp3"
   }
  ],
